import React from 'react';
import { Box, Grid, Paper, Stack, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import { Link as RouterLink } from 'react-router-dom';
import { GHG_SCOPE_COLORS, formatCo2eFromKg } from '../../constants/carbonVisualization';

export type CompanyFootprintOverviewProps = {
  companyName: string;
  industry: string;
  location: string;
  employeeCount: number;
  totalKg: number;
  score?: number | null;
  transactionCount: number;
  scope1Kg: number;
  scope2Kg: number;
  scope3Kg: number;
};

const NEXT_PAGES = [
  {
    title: 'Footprint rows',
    body: 'Bills and rows already counted in this footprint.',
    to: '/carbon-footprint?section=operational',
  },
  {
    title: 'Analytics',
    body: 'Disclosure charts and intensity for this inventory.',
    to: '/carbon-footprint?section=carbon-analytics',
  },
  {
    title: 'Reduction ideas',
    body: 'Measures aimed at the largest sources.',
    to: '/carbon-footprint?section=recommendations',
  },
  {
    title: 'Forecasting',
    body: 'Where this footprint is heading.',
    to: '/carbon-forecasting',
  },
];

const scopeParts = (scope1Kg: number, scope2Kg: number, scope3Kg: number) => ([
  { key: 'scope1', label: 'Scope 1', kg: Math.max(0, scope1Kg), color: GHG_SCOPE_COLORS.scope1.fill },
  { key: 'scope2', label: 'Scope 2', kg: Math.max(0, scope2Kg), color: GHG_SCOPE_COLORS.scope2.fill },
  { key: 'scope3', label: 'Scope 3', kg: Math.max(0, scope3Kg), color: GHG_SCOPE_COLORS.scope3.fill },
]);

const ringBackground = (parts: Array<{ kg: number; color: string }>): string => {
  const total = parts.reduce((sum, part) => sum + part.kg, 0);
  if (total <= 0) {
    return 'conic-gradient(#e2e8f0 0 100%)';
  }
  let cursor = 0;
  const stops = parts
    .filter((part) => part.kg > 0)
    .map((part) => {
      const start = cursor;
      cursor += (part.kg / total) * 100;
      return `${part.color} ${start}% ${cursor}%`;
    });
  return `conic-gradient(${stops.join(', ')})`;
};

const CompanyFootprintOverview: React.FC<CompanyFootprintOverviewProps> = ({
  companyName,
  industry,
  location,
  employeeCount,
  totalKg,
  score,
  transactionCount,
  scope1Kg,
  scope2Kg,
  scope3Kg,
}) => {
  const unit: 'kg' | 't' = totalKg >= 1000 ? 't' : 'kg';
  const facts = [industry, location, employeeCount > 0 ? `${employeeCount} people` : ''].filter(Boolean);
  const scoreValue = Number(score);
  const parts = scopeParts(scope1Kg, scope2Kg, scope3Kg);
  const scopeTotal = parts.reduce((sum, part) => sum + part.kg, 0);
  const perPerson = employeeCount > 0 && totalKg > 0 ? totalKg / employeeCount : 0;
  const metrics = [
    { label: 'This footprint', value: totalKg > 0 ? formatCo2eFromKg(totalKg, { unit }) : 'Not calculated yet' },
    {
      label: 'Carbon score',
      value: Number.isFinite(scoreValue) && scoreValue > 0 ? String(Math.round(scoreValue)) : '—',
    },
    { label: 'Per person', value: perPerson > 0 ? formatCo2eFromKg(perPerson, { unit: 'kg' }) : '—' },
    {
      label: 'Activity rows',
      value: transactionCount > 0 ? String(transactionCount) : 'None yet',
    },
  ];

  return (
    <Stack spacing={2} data-testid="company-footprint-overview">
      <Paper variant="outlined" sx={{ p: { xs: 2, md: 2.5 } }}>
        <Stack direction={{ xs: 'column', md: 'row' }} spacing={2.5} alignItems={{ md: 'center' }}>
          <Box
            aria-label="Scope share"
            sx={{
              width: 120,
              height: 120,
              borderRadius: '50%',
              background: ringBackground(parts),
              display: 'grid',
              placeItems: 'center',
              flexShrink: 0,
            }}
          >
            <Box
              sx={{
                width: 78,
                height: 78,
                borderRadius: '50%',
                bgcolor: 'background.paper',
                display: 'grid',
                placeItems: 'center',
                textAlign: 'center',
                px: 0.5,
              }}
            >
              <Typography variant="caption" sx={{ fontWeight: 800, lineHeight: 1.2 }}>
                {scopeTotal > 0 ? 'Scopes' : 'No split'}
              </Typography>
            </Box>
          </Box>
          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography variant="h5" sx={{ fontWeight: 800 }}>{companyName}</Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
              {facts.length > 0 ? facts.join(' · ') : 'Company details still to fill'}
            </Typography>
            <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" sx={{ mt: 1.5 }}>
              {parts.map((part) => {
                const share = scopeTotal > 0 ? Math.round((part.kg / scopeTotal) * 100) : 0;
                return (
                  <Typography key={part.key} variant="caption" sx={{ fontWeight: 700, color: part.color }}>
                    {`${part.label} ${share}%`}
                  </Typography>
                );
              })}
            </Stack>
          </Box>
        </Stack>
        {totalKg <= 0 ? (
          <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
            {`Add energy, fuel, or activity and this page will show the footprint for ${companyName}.`}
          </Typography>
        ) : null}
      </Paper>

      <Grid container spacing={1.5}>
        {metrics.map((metric) => (
          <Grid item xs={6} md={3} key={metric.label}>
            <Paper variant="outlined" sx={{ p: 1.5, height: '100%' }}>
              <Typography variant="caption" color="text.secondary">{metric.label}</Typography>
              <Typography variant="h6" sx={{ fontWeight: 800, mt: 0.25 }}>{metric.value}</Typography>
            </Paper>
          </Grid>
        ))}
      </Grid>

      <Grid container spacing={1.5}>
        {NEXT_PAGES.map((page) => (
          <Grid item xs={12} sm={6} md={3} key={page.to}>
            <Paper
              component={RouterLink}
              to={page.to}
              aria-label={page.title}
              variant="outlined"
              sx={{
                p: 1.5,
                height: '100%',
                display: 'block',
                textDecoration: 'none',
                color: 'inherit',
                '&:hover': { bgcolor: (theme) => alpha(theme.palette.primary.main, 0.06) },
              }}
            >
              <Typography variant="subtitle2" sx={{ fontWeight: 800 }}>{page.title}</Typography>
              <Typography variant="caption" color="text.secondary">{page.body}</Typography>
            </Paper>
          </Grid>
        ))}
      </Grid>
    </Stack>
  );
};

export default CompanyFootprintOverview;
