import { useQuery, useQueryClient, type QueryClient } from '@tanstack/react-query';
import { queryKeys } from '../../constants/queryKeys';
import ApiService from '../../services/api';
import type {
  ReportingCarbonFootprintPayload,
  ReportingComparisonsPayload,
} from '../../components/reporting/ReportingCarbonAnalyticsPanel';

const REPORTING_STALE_MS = 2 * 60_000;
export const READINESS_STALE_MS = 30_000;

export type ReportingBundleSection =
  | 'footprint'
  | 'comparisons'
  | 'readiness'
  | 'brsr'
  | 'iso14064'
  | 'iso14067'
  | 'cbam'
  | 'dashboard';

export type ReportingWorkspaceBundlePayload = {
  footprint?: ReportingCarbonFootprintPayload | null;
  comparisons?: ReportingComparisonsPayload | null;
  readiness?: Record<string, unknown> | null;
  brsr?: Record<string, unknown> | null;
  brsrAccessDenied?: {
    message?: string;
    code?: string;
    tier?: string;
    feature?: string;
    contactEmail?: string;
  } | null;
  iso14064?: Record<string, unknown> | null;
  iso14067?: Record<string, unknown> | null;
  cbam?: Record<string, unknown> | null;
  dashboard?: { quantificationSummary?: Record<string, unknown> | null } | null;
  reportCompleteness?: {
    needsDecision?: number;
    calculationQueued?: boolean;
    warning?: string | null;
  } | null;
};

export function invalidateReportingReadinessCaches(
  queryClient: QueryClient,
  period: string
) {
  void queryClient.invalidateQueries({
    queryKey: queryKeys.reporting.readinessOverview(period),
  });
  void queryClient.invalidateQueries({
    queryKey: ['reporting', 'workspace-bundle'],
  });
  void queryClient.invalidateQueries({
    queryKey: queryKeys.reporting.all,
  });
}

export function unwrapReportingPayload<T>(response: unknown): T | null {
  if (!response || typeof response !== 'object') {
    return null;
  }
  const record = response as Record<string, unknown>;
  return (record.data ?? response) as T;
}

const buildBundlePeriodsKey = (periods: Partial<Record<ReportingBundleSection, string>>) =>
  JSON.stringify(periods);

export function hydrateReportingBundleCaches(
  queryClient: QueryClient,
  periods: Partial<Record<ReportingBundleSection, string>>,
  payload: ReportingWorkspaceBundlePayload,
  includeAdvisory = false
) {
  if (payload.footprint && periods.footprint) {
    queryClient.setQueryData(queryKeys.reporting.footprint(periods.footprint), payload.footprint);
  }
  if (payload.comparisons && periods.comparisons) {
    queryClient.setQueryData(queryKeys.reporting.comparisons(periods.comparisons), payload.comparisons);
  }
  if (payload.readiness && periods.readiness) {
    queryClient.setQueryData(
      [...queryKeys.reporting.readinessOverview(periods.readiness), includeAdvisory] as const,
      payload.readiness
    );
  }
  if (payload.brsr && periods.brsr) {
    queryClient.setQueryData(queryKeys.reporting.brsr(periods.brsr), payload.brsr);
  }
  if (payload.iso14064 && periods.iso14064) {
    queryClient.setQueryData(queryKeys.reporting.iso14064(periods.iso14064), payload.iso14064);
  }
  if (payload.iso14067 && periods.iso14067) {
    queryClient.setQueryData(queryKeys.reporting.iso14067(periods.iso14067), payload.iso14067);
  }
  if (payload.cbam && periods.cbam) {
    queryClient.setQueryData(queryKeys.reporting.cbam(periods.cbam), payload.cbam);
  }
  if (payload.dashboard) {
    queryClient.setQueryData(queryKeys.reporting.dashboard, payload.dashboard);
  }
}

export function useReportingWorkspaceBundleQuery(options: {
  include: ReportingBundleSection[];
  periods: Partial<Record<ReportingBundleSection, string>>;
  includeAdvisory?: boolean;
  enabled?: boolean;
}) {
  const queryClient = useQueryClient();
  const includeAdvisory = options.includeAdvisory ?? false;
  const periodsKey = buildBundlePeriodsKey(options.periods);

  return useQuery({
    queryKey: [...queryKeys.reporting.workspaceBundle(options.include, periodsKey), includeAdvisory] as const,
    queryFn: async () => {
      const response = await ApiService.getReportingWorkspaceBundle({
        include: options.include,
        periods: options.periods,
        includeAdvisory,
      });
      const payload = unwrapReportingPayload<ReportingWorkspaceBundlePayload>(response) ?? {};
      hydrateReportingBundleCaches(queryClient, options.periods, payload, includeAdvisory);
      return payload;
    },
    enabled: (options.enabled ?? true) && options.include.length > 0,
    staleTime: options.include.includes('readiness') ? READINESS_STALE_MS : REPORTING_STALE_MS,
    refetchOnWindowFocus: options.include.includes('readiness'),
  });
}

export function useReportingDashboardQuery(enabled = true) {
  return useQuery({
    queryKey: queryKeys.reporting.dashboard,
    queryFn: async () => {
      const response = await ApiService.getReportingDashboard();
      return unwrapReportingPayload<{ quantificationSummary?: Record<string, unknown> | null }>(
        response
      );
    },
    enabled,
    staleTime: REPORTING_STALE_MS,
  });
}

